package net.civeira.phylax.feature.access.oauthclient.infrastructure.driver.rest;

import java.util.List;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.ws.rs.core.Response;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.generated.openapi.api.OauthClientBatchApi;

@RequiredArgsConstructor
@ApplicationScoped
public class OauthClientBatchController implements OauthClientBatchApi {

  /**
   * OauthClient
   *
   * @autogenerated BatchControllerGenerator
   */
  private final OauthClientDeleteController deleteController;

  /**
   * Disable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final OauthClientDisableController disableController;

  /**
   * Enable
   *
   * @autogenerated BatchControllerGenerator
   */
  private final OauthClientEnableController enableController;

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param withBackchannelLogoutUrl
   * @param withFrontchannelLogoutUrl
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response oauthClientApiBatchDelete(final List<String> uids, final String search,
      final Boolean withBackchannelLogoutUrl, final Boolean withFrontchannelLogoutUrl,
      final String code, final String tenant, final List<String> tenants) {
    return deleteController.oauthClientApiBatchDelete(uids, search, withBackchannelLogoutUrl,
        withFrontchannelLogoutUrl, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response oauthClientApiBatchDeleteQuery(final String batchId) {
    return deleteController.oauthClientApiBatchDeleteQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param withBackchannelLogoutUrl
   * @param withFrontchannelLogoutUrl
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response oauthClientApiBatchDisable(final List<String> uids, final String search,
      final Boolean withBackchannelLogoutUrl, final Boolean withFrontchannelLogoutUrl,
      final String code, final String tenant, final List<String> tenants) {
    return disableController.oauthClientApiBatchDisable(uids, search, withBackchannelLogoutUrl,
        withFrontchannelLogoutUrl, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response oauthClientApiBatchDisableQuery(final String batchId) {
    return disableController.oauthClientApiBatchDisableQuery(batchId);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param uids
   * @param search
   * @param withBackchannelLogoutUrl
   * @param withFrontchannelLogoutUrl
   * @param code
   * @param tenant
   * @param tenants
   * @return
   */
  @Override
  public Response oauthClientApiBatchEnable(final List<String> uids, final String search,
      final Boolean withBackchannelLogoutUrl, final Boolean withFrontchannelLogoutUrl,
      final String code, final String tenant, final List<String> tenants) {
    return enableController.oauthClientApiBatchEnable(uids, search, withBackchannelLogoutUrl,
        withFrontchannelLogoutUrl, code, tenant, tenants);
  }

  /**
   * @autogenerated BatchControllerGenerator
   * @param batchId
   * @return
   */
  @Override
  public Response oauthClientApiBatchEnableQuery(final String batchId) {
    return enableController.oauthClientApiBatchEnableQuery(batchId);
  }
}
